+#[test]
+fn arming_one_look_at_pick_disarms_the_other() {
+    let mut h = open_menu();
+    press(&mut h, menu::LOOK_AT_FACE);
+    assert!(h.state().state.look_at_armed && !h.state().state.look_at_plane_armed);
