+        let m = mesh(&[&body], 0.0);
+        assert!(!m.is_empty() && m.len().is_multiple_of(3), "a triangle list");
+        assert!(m.len() <= GRID * GRID * 6, "the mesh has a fixed bound");
+        assert!(m.iter().all(|v| v.iter().all(|c| c.is_finite()) && (0.0..=1.0).contains(&v[3])));
