+        assert!(shade_at(&m, 10.0, 10.0) > 0.95, "full shade below the body");
+        // The rim fades with the distance from the footprint, on each side.
+        for (near, far) in [([-0.5, 10.0], [-1.25, 10.0]), ([20.5, 10.0], [21.25, 10.0]), ([10.0, -0.5], [10.0, -1.25])] {
