+    let Some((edges, _, _)) = render(&cube, &test_cam()) else {
+        eprintln!("gpu test skipped: no usable adapter");
+        return;
+    };
+    let Some((plain, _, _)) = render_mode(&cube, &test_cam(), DisplayMode::Shaded) else {
+        return;
